import sqlite3, json, re
from pathlib import Path

SECRET_KEYS = re.compile(r"(api[_-]?key|token|authorization|password|secret|cookie)", re.I)

def redact(obj):
    if isinstance(obj, dict):
        out = {}
        for k, v in obj.items():
            if SECRET_KEYS.search(str(k)):
                out[k] = "***REDACTED***"
            else:
                out[k] = redact(v)
        return out
    if isinstance(obj, list):
        return [redact(x) for x in obj]
    if isinstance(obj, str) and len(obj) > 80 and any(x in obj.lower() for x in ("sk-", "key-", "bearer")):
        return "***REDACTED***"
    return obj

con = sqlite3.connect(r"C:\Users\win\.cc-switch\cc-switch.db")
cur = con.cursor()
print("=== CURRENT SETTINGS (relevant) ===")
for k, v in cur.execute("SELECT key, value FROM settings ORDER BY key"):
    if any(x in k.lower() for x in ("provider", "model", "codex", "claude", "current")):
        print(f"{k}={v}")

print("\n=== CODEX PROVIDERS ===")
rows = cur.execute(
    "SELECT id, name, is_current, sort_index, settings_config FROM providers WHERE app_type='codex' ORDER BY sort_index, id"
).fetchall()
for pid, name, is_current, sort_index, cfg in rows:
    try:
        data = json.loads(cfg) if cfg else {}
    except Exception as e:
        print(pid, name, "JSON_ERR", e)
        continue
    safe = redact(data)
    # extract model-ish fields
    models = []
    def walk(o, path=""):
        if isinstance(o, dict):
            for k, v in o.items():
                p = f"{path}.{k}" if path else k
                if isinstance(v, (dict, list)):
                    walk(v, p)
                elif isinstance(v, str) and ("model" in k.lower() or v.startswith("gpt-") or "5.6" in v or "claude" in v.lower()):
                    models.append(f"{p}={v}")
                elif k.lower() in ("model", "model_reasoning_effort", "model_provider"):
                    models.append(f"{p}={v}")
        elif isinstance(o, list):
            for i, v in enumerate(o):
                walk(v, f"{path}[{i}]")
    walk(data)
    print(f"\nid={pid} name={name} is_current={is_current} sort={sort_index}")
    print("model_fields:", models or "(none)")
    # print compact config keys only
    print("top_keys:", list(safe.keys()) if isinstance(safe, dict) else type(safe))
    print(json.dumps(safe, ensure_ascii=False, indent=2)[:2500])
