# Find sol references in codex/claude/cursor configs (no secrets dump)
roots = [
    Path(r"C:\Users\win\.codex"),
    Path(r"C:\Users\win\.claude"),
    Path(r"C:\Users\win\AppData\Roaming\Cursor\User"),
]
patterns = re.compile(r"gpt-5\.6-sol|5\.6-sol|gpt-5\.6-terra|gpt-5\.6-luna")
skip = {".git", "node_modules", "sessions", "session", "log", "logs", "cache", "tmp", ".tmp"}
for root in roots:
    if not root.exists():
        print("missing", root)
        continue
    print(f"\n=== scan {root} ===")
    count = 0
    for p in root.rglob("*"):
        if not p.is_file():
            continue
        if any(part.lower() in skip or part.startswith(".") and part not in {".codex"} for part in p.parts):
            # still allow scanning important files
            pass
        if any(s in p.parts for s in ("node_modules", ".git", "sessions", "archived_sessions", "vendor", "skills")):
            continue
        if p.suffix.lower() not in {".toml", ".json", ".jsonl", ".md", ".txt", ".yml", ".yaml"}:
            continue
        if p.stat().st_size > 5_000_000:
            continue
        try:
            text = p.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue
        if "5.6-sol" in text or "gpt-5.6-sol" in text:
            # redact lines with keys
            hits = []
            for i, line in enumerate(text.splitlines(), 1):
                if "5.6-sol" in line or "gpt-5.6-sol" in line:
                    if any(k in line.lower() for k in ("api_key", "token", "authorization", "sk-")):
                        continue
                    hits.append(f"L{i}:{line.strip()[:160]}")
            if hits:
                count += 1
                print(p)
                for h in hits[:8]:
                    print(" ", h)
    print("files_with_sol:", count)

